function parseKickTempRules(rules: string): KickTempSection[] {
  const sections: KickTempSection[] = [];
  let currentSection: KickTempSection | null = null;
  let currentData: string[] = [];

  rules.split('\n').forEach(line => {
    if (line.startsWith('⫻')) {
      if (currentSection) {
        sections.push(currentSection);
      }
      const parts = line.substring(1).split(':');
      currentSection = {
        name: parts[0],
        type: parts[1],
        place: '',
        data: []
      };
      currentData = [];
    } else if (currentSection) {
      currentSection.place += line + '\n';
      currentData.push(line);
    }
  });

  if (currentSection) {
    currentSection.data = currentData.join('\n');
    sections.push(currentSection);
  }

  return sections;
}

