// KickTempRules for TypeScript

// Section definitions
interface Section {
  name: 'context' | 'const' | 'content';
  type?: string;
  place: string;
  data: any; // JSON or plain text
}

// Rule for parsing sections
function parseSection(input: string): Section {
  const parts = input.split(':');
  const nameType = parts[0].split('/');
  return {
    name: nameType[0] as Section['name'],
    type: nameType[1],
    place: parts[1],
    data: parts.slice(2).join(':').trim(),
  };
}

// Example data
const example = `

⫻context:KickTempRules
Generate content according to these rules:
1. Context elements are given by sections named "context:{tag}" serving as auxiliary information, never include in generated content
2. Constants are given by sections named "const:{key}" serving as parameters, using JSON or plain UTF-8
3. Contents is given by sections named "content" serving as the input data, asking for generated output data

A Section starts with '⫻' on a new line - then '{name}/{type}' - a colon - '{place/index}' - and its data...

1. 'name' being a keyword or token: ['const', 'content', 'context']
2. 'type' being optional information: format, encoding, component type
3. data as indicated
4. a few empty lines until the end of the section


⫻const:user
Denis + Denise

⫻const:assistant
{ai}

⫻content:input
Convert the above KickTempRules to be used for generating TypeScript Code
`;

// Function to generate content based on KickTempRules
function generateContent(data: string) {
  const sections: Section[] = data.split('\n\n').map(parseSection);

  // Extract constants
  const constants = sections
    .filter((sec) => sec.name === 'const')
    .reduce((acc, sec) => {
      acc[sec.place] = sec.data;
      return acc;
    }, {} as { [key: string]: any });

  // Generate content based on "content" section
  const contentSection = sections.find((sec) => sec.name === 'content');
  if (!contentSection) {
    throw new Error('No "content" section found');
  }

  // Placeholder for generated content
  let generatedContent = '';

  // Example: Replace {user} with the value from constants
  generatedContent += contentSection.data.replace(/{([a-z]+)}/gi, (_, match) => {
    return constants[match];
  });

  return generatedContent;
}

// Call the generateContent function with the example data
const result = generateContent(example);
console.log(result);
